local HostBuilder = require(script.Parent.HostBuilder)
local LuaTypeProviderFactory = require(script.Parent.Parent.Parent.Extensions.LuaTypeProviderFactory)

local luaTypes = LuaTypeProviderFactory(game.ReplicatedStorage._robloxManifest.LuaTypes)

return function()
	describe("HostBuilder", function()
		it("should create a new instance", function()
			local builder = HostBuilder.new(luaTypes)
			expect(builder).to.be.ok()
			expect(builder.Properties).to.be.a("table")
		end)

		it("should allow configuration of services", function()
			local builder = HostBuilder.new(luaTypes)
			local servicesCalled = false

			builder:ConfigureServices(function(context, services)
				services:AddSingleton("testService", function()
					servicesCalled = true
				end)
			end)

			local host = builder:Build()
			host.Services:GetService("testService")

			expect(servicesCalled).to.equal(true)
		end)

		it("should not allow building more than once", function()
			local builder = HostBuilder.new(luaTypes)

			builder:Build()
			expect(function()
				builder:Build()
			end).to.throw()
		end)

		it("throw if not provide luaTypePrivider", function()
			expect(function()
				local builder = HostBuilder.new()
				builder:Build()
			end).to.throw("luaTypePrivider is required")
		end)

		it("add hosted service from hostBuilder", function()
			local runCount = 0
			local builder = HostBuilder.new(luaTypes)
			builder:ConfigureServices(function(_, collection)
				collection:AddHostedService(function()
					runCount += 1
					return { value = "测试" }
				end)
				collection:AddHostedService(function()
					runCount += 1
					return { value = "测试1" }
				end)
				collection:AddHostedService(function()
					runCount += 1
					return { value = "测试2" }
				end)
			end)

			local host = builder:Build()
			host:Start()
			expect(runCount).to.equal(3)
		end)
	end)
end
